import numpy as np

def correlate2d_3x3(image, kernel):
    image = np.asarray(image, dtype=np.float64)
    kernel = np.asarray(kernel, dtype=np.float64)
    H, W = image.shape
    out = np.zeros_like(image)
    for y in range(H):
        for x in range(W):
            acc = 0.0
            for j in (-1, 0, 1):
                for i in (-1, 0, 1):
                    yy = max(0, min(H - 1, y + j))
                    xx = max(0, min(W - 1, x + i))
                    acc += kernel[j + 1, i + 1] * image[yy, xx]
            out[y, x] = acc
    return out
